static int write_midx_internal(struct write_midx_opts *opts)
{
	struct repository *r = opts->source->odb->repo;
	struct strbuf midx_name = STRBUF_INIT;
	unsigned char midx_hash[GIT_MAX_RAWSZ];
	uint32_t start_pack;
	struct hashfile *f = NULL;
	struct lock_file lk = LOCK_INIT;
	struct tempfile *incr;
	struct write_midx_context ctx = {
		.preferred_pack_idx = NO_PREFERRED_PACK,
	 };
	struct multi_pack_index *midx_to_free = NULL;
	int bitmapped_packs_concat_len = 0;
	int pack_name_concat_len = 0;
	int dropped_packs = 0;
	int result = -1;
	struct strvec keep_hashes = STRVEC_INIT;
	struct chunkfile *cf;

	trace2_region_enter("midx", "write_midx_internal", r);

	ctx.repo = r;
	ctx.source = opts->source;

	ctx.version = ((opts->flags & MIDX_WRITE_COMPACT)
		       ? MIDX_VERSION_V2
		       : MIDX_VERSION_V1);
	repo_config_get_int(ctx.repo, "midx.version", &ctx.version);
	if (ctx.version != MIDX_VERSION_V1 && ctx.version != MIDX_VERSION_V2)

if (ctx.incremental)
	strbuf_addf(&midx_name,
		    "%s/pack/multi-pack-index.d/tmp_midx_XXXXXX",
		    opts->source->path);
else
	get_midx_filename(opts->source, &midx_name);
if (safe_create_leading_directories(r, midx_name.buf))
	die_errno(_("unable to create leading directories of %s"),
		  midx_name.buf);

if (!opts->packs_to_include || ctx.incremental) {
	struct multi_pack_index *m = get_multi_pack_index(opts->source);
	if (m && !midx_checksum_valid(m)) {
		warning(_("ignoring existing multi-pack-index; checksum mismatch"));
		m = NULL;
	}

	if (m) {
		/*
		 * Only reference an existing MIDX when not filtering
		 * which packs to include, since all packs and objects
		 * are copied blindly from an existing MIDX if one is
		 * present.
		 */
		if (ctx.incremental)
			ctx.base_midx = m;
		if (!opts->packs_to_include)
			ctx.m = m;
	}
}

/*
 * If compacting MIDX layer(s) in the range [from, to], then the
 * compacted MIDX will share the same base MIDX as 'from',
 * unless a custom --base is specified (see below).
 */
if (ctx.compact)
	ctx.base_midx = ctx.compact_from->base_midx;

if (opts->incremental_base) {
	if (!strcmp(opts->incremental_base, "none")) {
		ctx.base_midx = NULL;
	} else {
		while (ctx.base_midx) {
			const char *cmp = midx_get_checksum_hex(ctx.base_midx);
			if (!strcmp(opts->incremental_base, cmp))
				break;

			ctx.base_midx = ctx.base_midx->base_midx;
		}

		if (!ctx.base_midx) {
			error(_("could not find base MIDX '%s'"),
			      opts->incremental_base);
			goto cleanup;
		}
	}
}

ctx.nr = 0;
ctx.alloc = ctx.m ? ctx.m->num_packs + ctx.m->num_packs_in_base : 16;
ctx.info = NULL;
ALLOC_ARRAY(ctx.info, ctx.alloc);

if (ctx.incremental) {
	struct multi_pack_index *m = ctx.base_midx;
	while (m) {
		if (opts->flags & MIDX_WRITE_BITMAP && load_midx_revindex(m)) {
			error(_("could not load reverse index for MIDX %s"),
			      midx_get_checksum_hex(m));
			goto cleanup;
		}
		ctx.num_multi_pack_indexes_before++;
		m = m->base_midx;
	}
} else if (ctx.m && !ctx.compact && fill_packs_from_midx(&ctx)) {
	goto cleanup;
}

start_pack = ctx.nr;

ctx.pack_paths_checked = 0;
if (opts->flags & MIDX_PROGRESS)
	ctx.progress = start_delayed_progress(r,
					      _("Adding packfiles to multi-pack-index"), 0);
else
	ctx.progress = NULL;

if (ctx.compact) {
	int bitmap_order = 0;
	if (opts->preferred_pack_name)
		bitmap_order |= 1;

				strvec_push(&keep_hashes,
					    midx_get_checksum_hex(layers[--layers_nr]));

			strvec_push(&keep_hashes,
				    hash_to_hex_algop(midx_hash,
						     r->hash_algo));
		}

		free(layers);

		if (is_lock_file_locked(&lk))
			for (size_t i = 0; i < keep_hashes.nr; i++)
				fprintf(get_lock_file_fp(&lk), "%s\n",
					keep_hashes.v[i]);
	} else {
		strvec_push(&keep_hashes,
			    hash_to_hex_algop(midx_hash, r->hash_algo));
	}

	if (ctx.m || ctx.base_midx)
		odb_close(ctx.repo->objects);

	if (is_lock_file_locked(&lk)) {
		if (commit_lock_file(&lk) < 0)
			die_errno(_("could not write multi-pack-index"));

		clear_midx_files(opts->source, &keep_hashes, ctx.incremental);
	}
	result = 0;

cleanup:
	for (size_t i = 0; i < ctx.nr; i++) {
		if (ctx.info[i].p) {
			close_pack(ctx.info[i].p);
			free(ctx.info[i].p);
		}
		free(ctx.info[i].pack_name);
	}

	free(ctx.info);
	free(ctx.entries);
	free(ctx.pack_perm);
	free(ctx.pack_order);
